  #endif
}
#if FLAME_EDGE || LIT_ICON
  float cloudHash(vec2 p) {
    p.y = mod(p.y,8.0);
    vec3 q = fract(vec3(p.xyx)*vec3(0.1031,0.1030,0.0973));
    q += dot(q,q.yzx+33.33);
    return fract((q.x+q.y)*q.z);
  }
  float cloud(vec2 p) {
    vec2 cell=floor(p), f=fract(p);f=f*f*(3.0-2.0*f);
    return mix(mix(cloudHash(cell),cloudHash(cell+vec2(1,0)),f.x),
               mix(cloudHash(cell+vec2(0,1)),cloudHash(cell+1.0),f.x),f.y);
  }
#endif
float coverage(vec2 uv) {
  vec2 inside = step(vec2(0.0),uv) * step(uv,vec2(1.0));
  return CCSampleWithAlphaSeparated(cc_spriteTexture,clamp(uv,0.0,1.0)).a * inside.x * inside.y;
}
