    float radius=clamp(length(p)*1.42,0.0,1.0);
    float peak=max(color.r,max(color.g,color.b));
    float gain=min(0.38,1.0/max(mix(peak,1.0,0.20),0.01)-1.0);
    float intensity=pow(color.a,mix(2.2,0.85,radius));
    return vec4(vec3(gain*intensity*(1.0-smoothstep(-0.8,0.8,edge))),0.0);
  #elif INNER_GLOW
    float a=coverage(uv0);
    float neighbors=0.0;
    for(int i=0;i<8;i++){
      float angle=float(i)*0.78539816;
      neighbors+=coverage(uv0+vec2(cos(angle),sin(angle))*0.09);
    }
    float rim=1.0-neighbors*0.125;
    vec3 hue=color.rgb/max(0.01,max(color.r,max(color.g,color.b)));
    float edge=clamp(rim/0.57,0.0,1.0);
    float strength=a*color.a*(0.11+0.89*(exp2(3.0*edge)-1.0)/7.0);
    return vec4(hue*strength,0.0);
  #elif STARS
    return starLayer();
  #elif ICON_HALO
    vec2 uv = (uv0 - 0.5) * (58.0/48.0) + 0.5;
    #if FLAME_EDGE
      #if STILL
        float time = 0.0;
      #else
        float time = crestTime();
      #endif
      vec2 p = uv*vec2(8.0,3.6)+vec2(1.7,time*(8.0/5.6));
      float noise = cloud(p)*0.72+cloud(p*2.0+vec2(5.1,2.6))*0.28;
      float cloudMask = smoothstep(0.28,0.70,noise);
      float radius = pow(clamp(length(uv-0.5)*2.0,0.0,1.0),0.7);
      float reach = mix(3.5,8.0,mix(0.45,cloudMask,0.52+0.48*radius));
    #endif
    float halo = 0.0;
    for (int i=0; i<12; ++i) {
      float a = float(i) * 0.52359878;
      vec2 dir = vec2(cos(a),sin(a))/48.0;
      #if FLAME_EDGE
        halo += 0.45 * coverage(uv+dir*(reach*0.55));
        halo += coverage(uv+dir*reach+vec2(0.0,cloudMask*0.022));
      #else
        halo += coverage(uv+dir*2.5) + coverage(uv+dir*4.8)*0.82;
      #endif
    }
    #if FLAME_EDGE
      vec2 cellCorner = max(abs((uv0-0.5)*58.0)-vec2(18.5),vec2(0.0));
      float cellMask = 1.0-smoothstep(8.0,9.0,length(cellCorner));
      halo = max(coverage(uv),min(1.0,halo*0.64)) * cellMask;
      #if DISPERSE
        float progress=erosion.x;
        vec2 field=(uv-0.5)*mix(11.5,4.6,progress)+erosion.yz+progress*vec2(3.2,-2.7);
        float pits=cloud(field)*0.76+cloud(field*2.17+vec2(9.4,3.1))*0.24;
        float threshold=mix(-0.04,1.04,progress);
        halo *= smoothstep(threshold-0.012,threshold+0.012,pits);
      #endif
    #else
      halo = min(1.0,halo*0.34) * (1.0-coverage(uv));
    #endif
    #if FLAME_EDGE
      vec3 ink = color.rgb;
    #else
      vec3 ink = mix(color.rgb,vec3(1.0),0.37);
    #endif
    #if GOLD
      ink = flameSpectrum(uv.x*8.4+uv.y*3.2+noise*3.6);
    #endif
    return vec4(ink,halo*color.a);
  #elif SHEEN
    vec4 face = CCSampleWithAlphaSeparated(cc_spriteTexture,uv0);
    #if !STILL
      float band=1.0-smoothstep(0.02,0.13,abs(uv0.x+0.35*uv0.y-(mod(cc_time.x,3.0)*1.2-0.3)));
      face.rgb=mix(face.rgb,vec3(1.0,0.94,0.70),band*0.58);
    #endif
    return vec4(face.rgb,face.a*color.a);
  #elif LIT_ICON
    vec4 icon = CCSampleWithAlphaSeparated(cc_spriteTexture,uv0);
    float axis = uv0.x + 0.34*uv0.y;
    #if STILL
      float time = 0.0;
      float center = 0.68;
    #else
      float time = crestTime();
      const float sweepPeriod = 8.4;
      float center = -0.20 + mod(time+color.r*sweepPeriod,sweepPeriod)*1.20;
    #endif
    float band = 1.0-smoothstep(0.061,0.074,abs(axis-center));
    icon.rgb = mix(icon.rgb,vec3(1.0,0.78,0.33),band*0.82);
    vec2 pixel = (uv0-0.5)*vec2(48.0,-48.0);
    float seed = floor(color.r*255.0+0.5);
    vec2 source=vec2(31.6+seed*0.17,4.3+seed*0.061);
    vec2 plumeUV=pixel*vec2(0.118,0.083)+source-vec2(0.0,time*0.94);
    float plume=cloud(plumeUV)*0.7+cloud(pixel*vec2(0.21,0.155)+source.yx+vec2(11.9,-time*1.67))*0.3;
    float upper=-9.0+33.0*plume;
    float veil=smoothstep(-24.0,-16.0,pixel.y)*(1.0-smoothstep(upper-5.0,upper+1.0,pixel.y));
    vec3 flame=flameSpectrum(pixel.x*0.082+time*1.122+plume*1.5);
    icon.rgb=mix(icon.rgb,max(icon.rgb,flame),veil*(0.20+0.14*plume));
    return vec4(icon.rgb,icon.a*color.a);
  #else
    return CCSampleWithAlphaSeparated(cc_spriteTexture,uv0)*color;
  #endif
}
